"""Tests for release_bot's github_client checklist/version helpers, auth
selection, and PyGithub-backed API wrappers.
"""

from datetime import UTC, date, datetime

import github_client as github
import pytest
from github import Auth

CHECKLIST_BODY = """## Release 2026.7.22.1

### Changes

- [ ] `abc1234` chore: bump version by bot@example.com
- [x] **fix: real bug** (#5) by human@example.com

---
*This release was automatically generated by the Concourse release pipeline.*
*Closing this issue will trigger the production deployment.*
"""

FULLY_CHECKED_BODY = CHECKLIST_BODY.replace(
    "- [ ] `abc1234` chore: bump version by bot@example.com",
    "- [x] `abc1234` chore: bump version by bot@example.com",
)

UPPERCASE_CHECKED_BODY = CHECKLIST_BODY.replace(
    "- [ ] `abc1234` chore: bump version by bot@example.com",
    "- [X] `abc1234` chore: bump version by bot@example.com",
)

NO_CHECKLIST_BODY = "Just some notes, no checklist here."


def test_checklist_status_counts_checked_and_total():
    """One of two checklist lines is checked."""
    checked, total = github.checklist_status(CHECKLIST_BODY)
    assert checked == 1
    assert total == 2


def test_checklist_status_empty_body_is_zero_zero():
    """A body with no checklist lines reports (0, 0)."""
    assert github.checklist_status(NO_CHECKLIST_BODY) == (0, 0)


def test_is_fully_checked_false_when_any_line_unchecked():
    """Not fully checked while at least one line is unchecked."""
    assert github.is_fully_checked(CHECKLIST_BODY) is False


def test_is_fully_checked_true_when_all_lines_checked():
    """Fully checked once every checklist line is checked."""
    assert github.is_fully_checked(FULLY_CHECKED_BODY) is True


def test_checklist_status_counts_uppercase_x_as_checked():
    """GitHub treats "[X]" (uppercase) the same as "[x]" -- so must we."""
    checked, total = github.checklist_status(UPPERCASE_CHECKED_BODY)
    assert checked == 2
    assert total == 2
    assert github.is_fully_checked(UPPERCASE_CHECKED_BODY) is True


def test_is_fully_checked_false_when_no_checklist_lines():
    """A body with zero checklist lines is never "ready" -- nothing to check."""
    assert github.is_fully_checked(NO_CHECKLIST_BODY) is False


def test_extract_version_finds_release_header():
    """Version is parsed from the "## Release X" header."""
    assert github.extract_version(CHECKLIST_BODY) == "2026.7.22.1"


def test_extract_version_returns_none_without_header():
    """No version header present -- returns None."""
    assert github.extract_version(NO_CHECKLIST_BODY) is None


_ENV_VARS = (
    "GITHUB_APP_ID",
    "GITHUB_APP_INSTALLATION_ID",
    "GITHUB_APP_PRIVATE_KEY",
)


@pytest.fixture(autouse=True)
def _clear_github_env(monkeypatch):
    """Auth-selection tests must start from a clean slate -- os.environ is
    process-global, and a var left over from one test would silently change
    which branch of _build_auth() the next test exercises.
    """
    for var in _ENV_VARS:
        monkeypatch.delenv(var, raising=False)


def test_build_auth_raises_without_any_credentials():
    """No App credentials set -- raises with a clear message."""
    with pytest.raises(RuntimeError, match="GITHUB_APP_ID"):
        github._build_auth()


def test_build_auth_raises_with_partial_credentials(monkeypatch):
    """Only some App credentials set -- still raises rather than silently
    falling back or passing partial creds to PyGithub.
    """
    monkeypatch.setenv("GITHUB_APP_ID", "12345")
    monkeypatch.setenv("GITHUB_APP_INSTALLATION_ID", "67890")
    with pytest.raises(RuntimeError, match="must all be set"):
        github._build_auth()


def test_build_auth_uses_app_auth_when_app_credentials_are_set(monkeypatch):
    """App auth is used when all three App credentials are present."""
    monkeypatch.setenv("GITHUB_APP_ID", "12345")
    monkeypatch.setenv("GITHUB_APP_INSTALLATION_ID", "67890")
    monkeypatch.setenv(
        "GITHUB_APP_PRIVATE_KEY",
        "-----BEGIN RSA PRIVATE KEY-----",  # pragma: allowlist secret
    )
    auth = github._build_auth()
    assert isinstance(auth, Auth.AppInstallationAuth)


def test_build_auth_rejects_non_numeric_app_id(monkeypatch):
    """A non-numeric GITHUB_APP_ID fails fast with a clear error, not a
    late/confusing failure from PyGithub or the GitHub API.
    """
    monkeypatch.setenv("GITHUB_APP_ID", "not-a-number")
    monkeypatch.setenv("GITHUB_APP_INSTALLATION_ID", "67890")
    monkeypatch.setenv(
        "GITHUB_APP_PRIVATE_KEY",
        "-----BEGIN RSA PRIVATE KEY-----",  # pragma: allowlist secret
    )
    with pytest.raises(RuntimeError, match="must be numeric"):
        github._build_auth()


def test_build_auth_rejects_non_numeric_installation_id(monkeypatch):
    """Same fail-fast behavior for a non-numeric installation id."""
    monkeypatch.setenv("GITHUB_APP_ID", "12345")
    monkeypatch.setenv("GITHUB_APP_INSTALLATION_ID", "not-a-number")
    monkeypatch.setenv(
        "GITHUB_APP_PRIVATE_KEY",
        "-----BEGIN RSA PRIVATE KEY-----",  # pragma: allowlist secret
    )
    with pytest.raises(RuntimeError, match="must be numeric"):
        github._build_auth()


class _FakeLabel:
    def __init__(self, name):
        self.name = name


class _FakeAuthor:
    def __init__(self, name, date=None):
        self.name = name
        self.date = date


class _FakeGitCommit:
    def __init__(self, message, author_name, commit_date=None):
        self.message = message
        self.author = _FakeAuthor(author_name, commit_date)


class _FakeParent:
    def __init__(self, sha):
        self.sha = sha


class _FakeCommit:
    def __init__(self, sha, message, author_name, url, parents=()):
        self.sha = sha
        self.commit = _FakeGitCommit(message, author_name)
        self.html_url = url
        self.parents = [_FakeParent(parent) for parent in parents]


class _FakeTag:
    def __init__(self, name):
        self.name = name


class _FakeBranch:
    def __init__(self, name, commit_date=None):
        self.name = name
        self.commit = _FakeCommit("sha", "Release", "ci", "https://x/sha")
        self.commit.commit = _FakeGitCommit("Release", "ci", commit_date)


class _FakeComparison:
    def __init__(self, status, commits, total_commits=None):
        self.status = status
        self.commits = commits
        self.total_commits = (
            len(commits or []) if total_commits is None else total_commits
        )


class _FakeIssue:
    def __init__(self, number, title, body, labels):
        self.number = number
        self.title = title
        self.body = body
        self.html_url = f"https://github.com/mitodl/thing/issues/{number}"
        self.labels = [_FakeLabel(name) for name in labels]
        self.comments = []
        self.state = "open"
        self.closed_at = None
        self.pull_request = None
        self.updated_at = datetime(2026, 10, 29, 15, 38, 26, tzinfo=UTC)

    def add_to_labels(self, label):
        self.labels.append(_FakeLabel(label))

    def create_comment(self, body):
        self.comments.append(body)

    def edit(self, **kwargs):
        if "state" in kwargs:
            self.state = kwargs["state"]
            if self.state == "closed":
                self.closed_at = datetime(2026, 10, 29, 15, 38, 26, tzinfo=UTC)


class _FakeDeploymentStatus:
    def __init__(self, state, target_url=None):
        self.state = state
        self.created_at = datetime(2026, 9, 2, 12, 0, tzinfo=UTC)
        self.target_url = target_url


class _FakeDeployment:
    def __init__(self, deployment_id, ref, environment, statuses, sha="deadbeef"):
        self.id = deployment_id
        self.ref = ref
        self.sha = sha
        self.environment = environment
        self.created_at = datetime(2026, 9, 2, 11, 0, tzinfo=UTC)
        self._statuses = statuses

    def get_statuses(self):
        return list(self._statuses)


class _FakeRepo:
    default_branch = "main"

    def __init__(  # noqa: PLR0913
        self,
        tags=(),
        comparison=None,
        commits=(),
        issues=(),
        branches=(),
        deployments=(),
    ):
        self._tags = tags
        self._comparison = comparison
        self._commits = commits
        self._branches = branches
        self._deployments = deployments
        self._issues = {issue.number: issue for issue in issues}
        self.label_queries: list[str] = []

    def get_deployments(self, environment=None, **_kwargs):
        return [
            deployment
            for deployment in self._deployments
            if environment in (None, deployment.environment)
        ]

    def get_tags(self):
        return list(self._tags)

    def get_branches(self):
        return list(self._branches)

    def compare(self, base, head):
        assert base in {t.name for t in self._tags}
        assert head == self.default_branch
        return self._comparison

    def get_commits(self):
        return list(self._commits)

    def get_issues(self, state=None, labels=None, **_kwargs):
        assert state in {"open", "closed", "all"}
        # The issues API ANDs the labels it is given; every caller asks for one.
        (label,) = labels
        self.label_queries.append(label)
        issues = [
            issue
            for issue in sorted(
                self._issues.values(), key=lambda i: i.number, reverse=True
            )
            if label in {lbl.name for lbl in issue.labels}
        ]
        if state != "all":
            issues = [issue for issue in issues if issue.state == state]
        return issues

    def get_issue(self, number):
        return self._issues[number]


class _FakeGithub:
    def __init__(self, repo):
        self._repo = repo

    def get_repo(self, slug):
        assert slug == "mitodl/thing"
        return self._repo


@pytest.fixture
def fake_repo(monkeypatch):
    """Patch _get_client() to return a Github stub wrapping the given repo."""

    def _install(repo):
        monkeypatch.setattr(github, "_get_client", lambda: _FakeGithub(repo))
        return repo

    return _install


def test_commits_since_last_tag_uses_compare_when_a_tag_exists(fake_repo):
    """Compares tag..default_branch and maps PyGithub Commit fields.

    Exercises _commits_since_last_tag_sync() directly rather than the public
    async wrapper -- pytest-asyncio's per-test event loop churn was observed
    to desync the process-global asyncio event loop that
    tests/test_example_correct_pattern.py's module-level Pulumi mocks depend
    on, breaking an unrelated, already-collected test module. The sync
    helpers carry all the logic under test; the async wrappers are a thin,
    obviously-correct asyncio.to_thread() passthrough.
    """
    fake_repo(
        _FakeRepo(
            tags=[_FakeTag("2026.07.01.1"), _FakeTag("not-a-release-tag")],
            comparison=_FakeComparison(
                "ahead", [_FakeCommit("abc123", "fix: bug", "me", "https://x/abc123")]
            ),
        )
    )
    commits = github._commits_since_last_tag_sync("mitodl/thing")["commits"]
    assert commits == [
        {
            "sha": "abc123",
            "message": "fix: bug",
            "author": "me",
            "url": "https://x/abc123",
        }
    ]


def test_commits_since_last_tag_lists_a_diverged_comparison(fake_repo):
    """An in-flight hotfix's tag is off main, so the comparison diverges.

    GitHub still lists main's commits since the merge base (live, 2026-10-09:
    a diverged compare with ahead_by=71 listed all 71), and they are exactly
    what the next release would carry -- so they must not read as nothing.
    """
    fake_repo(
        _FakeRepo(
            tags=[_FakeTag("2026.07.01.1")],
            comparison=_FakeComparison(
                "diverged",
                [_FakeCommit("abc123", "fix: bug", "me", "https://x/abc123")],
            ),
        )
    )
    unreleased = github._commits_since_last_tag_sync("mitodl/thing")
    assert [c["sha"] for c in unreleased["commits"]] == ["abc123"]
    assert unreleased["omitted"] == 0


def test_commits_since_last_tag_survives_an_empty_commit_message(fake_repo):
    """Git allows an empty message; it must not take the whole reply down."""
    fake_repo(
        _FakeRepo(
            tags=[_FakeTag("2026.07.01.1")],
            comparison=_FakeComparison(
                "ahead", [_FakeCommit("abc123", "", "me", "https://x/abc123")]
            ),
        )
    )
    unreleased = github._commits_since_last_tag_sync("mitodl/thing")
    assert [c["sha"] for c in unreleased["commits"]] == ["abc123"]


def test_commits_since_last_tag_falls_back_to_commit_history_without_a_tag(fake_repo):
    """No release tag exists -- falls back to plain commit history."""
    fake_repo(
        _FakeRepo(
            tags=[],
            commits=[_FakeCommit("def456", "chore: bump", "me", "https://x/def456")],
        )
    )
    commits = github._commits_since_last_tag_sync("mitodl/thing")["commits"]
    assert commits == [
        {
            "sha": "def456",
            "message": "chore: bump",
            "author": "me",
            "url": "https://x/def456",
        }
    ]


def test_open_release_issues_maps_fields(fake_repo):
    """Maps PyGithub Issue fields to the plain-dict shape bot.py expects."""
    fake_repo(
        _FakeRepo(
            issues=[_FakeIssue(42, "Release app", "## Release 2026.7.2.1", ["release"])]
        )
    )
    issues = github._open_release_issues_sync("mitodl/thing")
    assert issues == [
        {
            "number": 42,
            "title": "Release app",
            "url": "https://github.com/mitodl/thing/issues/42",
            "body": "## Release 2026.7.2.1",
            "labels": ["release"],
        }
    ]


def test_add_issue_label_adds_label_to_the_matching_issue(fake_repo):
    """Adds the label to the issue looked up by number."""
    repo = fake_repo(
        _FakeRepo(issues=[_FakeIssue(42, "Release app", "body", ["release"])])
    )
    github._add_issue_label_sync("mitodl/thing", 42, github.PROMOTE_READY_LABEL)
    assert github.PROMOTE_READY_LABEL in [lbl.name for lbl in repo.get_issue(42).labels]


def test_close_release_issue_comments_and_closes(fake_repo):
    """Comments on the issue, then closes it -- both actions, in order."""
    repo = fake_repo(
        _FakeRepo(issues=[_FakeIssue(42, "Release app", "body", ["release"])])
    )
    github._close_release_issue_sync("mitodl/thing", 42, "Promoted by @tmacey.")
    issue = repo.get_issue(42)
    assert issue.comments == ["Promoted by @tmacey."]
    assert issue.state == "closed"


